-- Fresh DEVELOPMENT projects only. Never run this baseline against production.
-- Schema captured read-only from cxtsnupbfqqosvzhwqyw on 2026-09-06.
-- No production users, messages, quiz history, credentials or storage objects.
SET search_path = public, extensions;
CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA public;
CREATE TYPE public.bloom_level_enum AS ENUM ('0_unseen','1_remember','2_understand','3_apply','4_analyze');
CREATE SEQUENCE public.music_id_seq;

CREATE TABLE public."events" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "title" text NOT NULL,
  "description" text,
  "start_time" timestamp with time zone NOT NULL,
  "end_time" timestamp with time zone,
  "location" text,
  "url" text NOT NULL,
  "category" text,
  "scraped_at" timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  "embedding" vector(384)
);

CREATE TABLE public."messages" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "session_id" uuid NOT NULL,
  "role" text NOT NULL,
  "content" text NOT NULL,
  "metadata" jsonb DEFAULT '{}'::jsonb,
  "created_at" timestamp with time zone DEFAULT now(),
  "response_for" uuid,
  "is_summary" boolean NOT NULL,
  "has_been_summarised" boolean DEFAULT false
);

CREATE TABLE public."music" (
  "id" bigint DEFAULT nextval('music_id_seq'::regclass) NOT NULL,
  "name" text NOT NULL,
  "ragam_name" text,
  "artist" text,
  "performance_type" text,
  "description" text,
  "lyrics" text,
  "audio_url" text,
  "sheet_music_url" text,
  "duration" integer,
  "tempo" text,
  "tala" text,
  "raga_characteristics" text,
  "emotional_context" text,
  "associated_characters" text[],
  "metadata" jsonb,
  "embedding" vector(384),
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now()
);

CREATE TABLE public."ornaments" (
  "id" text NOT NULL,
  "name" text NOT NULL,
  "path_d" text NOT NULL,
  "tooltip_position" jsonb NOT NULL,
  "description" text NOT NULL,
  "image_url" text,
  "metadata" jsonb,
  "embedding" vector(384),
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now()
);

CREATE TABLE public."quiz_question" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "quiz_id" uuid NOT NULL,
  "display_id" integer,
  "concept_id" character varying(255) NOT NULL,
  "target_level" bloom_level_enum NOT NULL,
  "misconception_target" boolean DEFAULT false NOT NULL,
  "question" text NOT NULL,
  "options" jsonb NOT NULL,
  "correct_answer" text NOT NULL,
  "explanation" text,
  "distractor_map" jsonb,
  "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "sequence_no" integer,
  "selected_answer" text,
  "is_correct" boolean,
  "response_ms" integer,
  "answered_at" timestamp with time zone
);

CREATE TABLE public."quiz_session" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "user_id" character varying(255) NOT NULL,
  "source" text DEFAULT 'adaptive'::text NOT NULL,
  "selected_concepts" jsonb,
  "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "submitted_at" timestamp with time zone,
  "policy_version" text,
  "session_state" jsonb,
  "status" text DEFAULT 'active'::text NOT NULL
);

CREATE TABLE public."sessions" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "user_id" uuid,
  "title" text DEFAULT 'New Conversation'::text,
  "created_at" timestamp with time zone DEFAULT now()
);

CREATE TABLE public."user_proficiency_state" (
  "user_id" character varying(255) NOT NULL,
  "node_id" character varying(255) NOT NULL,
  "bloom_level" bloom_level_enum DEFAULT '0_unseen'::bloom_level_enum NOT NULL,
  "misconception_flag" boolean DEFAULT false,
  "last_evidence" text,
  "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
  "last_reasoning" text,
  "last_confidence" double precision
);

