ALTER TABLE public."sessions" ADD CONSTRAINT "sessions_pkey" PRIMARY KEY (id);
ALTER TABLE public."user_proficiency_state" ADD CONSTRAINT "user_proficiency_state_pkey" PRIMARY KEY (user_id, node_id);
