ALTER TABLE public."messages" ADD CONSTRAINT "messages_session_id_fkey" FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE;
ALTER TABLE public."quiz_question" ADD CONSTRAINT "quiz_question_quiz_id_fkey" FOREIGN KEY (quiz_id) REFERENCES quiz_session(id) ON DELETE CASCADE;
ALTER TABLE public."sessions" ADD CONSTRAINT "sessions_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id);
