CREATE INDEX idx_quiz_question_quiz_id ON public.quiz_question USING btree (quiz_id);
CREATE INDEX idx_quiz_question_concept_id ON public.quiz_question USING btree (concept_id);
CREATE INDEX idx_user_proficiency_user_id ON public.user_proficiency_state USING btree (user_id);
CREATE INDEX idx_user_proficiency_node_id ON public.user_proficiency_state USING btree (node_id);
CREATE INDEX idx_user_proficiency_bloom_level ON public.user_proficiency_state USING btree (bloom_level);
CREATE INDEX idx_user_proficiency_misconception ON public.user_proficiency_state USING btree (misconception_flag) WHERE (misconception_flag = true);
