CREATE INDEX idx_ornaments_search ON public.ornaments USING gin (to_tsvector('english'::regconfig, ((name || ' '::text) || description)));
CREATE INDEX idx_music_name ON public.music USING btree (name);
CREATE INDEX idx_music_ragam ON public.music USING btree (ragam_name);
