CREATE INDEX idx_music_embedding ON public.music USING ivfflat (embedding vector_cosine_ops);
CREATE INDEX idx_music_search ON public.music USING gin (to_tsvector('english'::regconfig, ((((((((((COALESCE(name, ''::text) || ' '::text) || COALESCE(ragam_name, ''::text)) || ' '::text) || COALESCE(artist, ''::text)) || ' '::text) || COALESCE(description, ''::text)) || ' '::text) || COALESCE(raga_characteristics, ''::text)) || ' '::text) || COALESCE(emotional_context, ''::text))));
CREATE INDEX idx_music_characters ON public.music USING gin (associated_characters);
CREATE INDEX idx_messages_has_been_summarised ON public.messages USING btree (has_been_summarised);
CREATE INDEX idx_messages_session_id_created_at ON public.messages USING btree (session_id, created_at);
CREATE INDEX idx_messages_response_for ON public.messages USING btree (response_for);

CREATE OR REPLACE FUNCTION public.update_user_proficiency_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.match_events(query_embedding vector, match_threshold double precision DEFAULT 0.5, match_count integer DEFAULT 5)
 RETURNS TABLE(id bigint, title text, description text, start_time timestamp with time zone, end_time timestamp with time zone, location text, url text, embedding vector, similarity double precision)
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    events.id,
    events.title,
    events.description,
    events.start_time,
    events.end_time,
    events.location,
    events.url,
    events.embedding,
    (1 - (events.embedding <=> query_embedding))::float as similarity
  FROM events
  WHERE events.embedding IS NOT NULL
    AND 1 - (events.embedding <=> query_embedding) > match_threshold
  ORDER BY events.embedding <=> query_embedding
  LIMIT match_count;
END;
$function$;

CREATE OR REPLACE FUNCTION public.match_music(query_embedding vector, match_threshold double precision, match_count integer)
 RETURNS TABLE(id bigint, name text, ragam_name text, artist text, performance_type text, description text, lyrics text, audio_url text, sheet_music_url text, duration integer, tempo text, tala text, raga_characteristics text, emotional_context text, associated_characters text[], metadata jsonb, similarity double precision)
 LANGUAGE sql
 STABLE
AS $function$
  SELECT
    music.id,
    music.name,
    music.ragam_name,
    music.artist,
    music.performance_type,
    music.description,
    music.lyrics,
    music.audio_url,
    music.sheet_music_url,
    music.duration,
    music.tempo,
    music.tala,
    music.raga_characteristics,
    music.emotional_context,
    music.associated_characters,
    music.metadata,
    1 - (music.embedding <=> query_embedding) AS similarity
  FROM music
  WHERE music.embedding IS NOT NULL
  AND 1 - (music.embedding <=> query_embedding) > match_threshold
  ORDER BY music.embedding <=> query_embedding
  LIMIT match_count;
$function$;

CREATE OR REPLACE FUNCTION public.match_ornaments(query_embedding vector, match_threshold double precision, match_count integer)
 RETURNS TABLE(id text, name text, path_d text, tooltip_position jsonb, description text, image_url text, metadata jsonb, similarity double precision)
 LANGUAGE sql
 STABLE
AS $function$
  SELECT
    ornaments.id,
    ornaments.name,
    ornaments.path_d,
    ornaments.tooltip_position,
    ornaments.description,
    ornaments.image_url,
    ornaments.metadata,
    1 - (ornaments.embedding <=> query_embedding) AS similarity
  FROM ornaments
  WHERE ornaments.embedding IS NOT NULL
  AND 1 - (ornaments.embedding <=> query_embedding) > match_threshold
  ORDER BY ornaments.embedding <=> query_embedding
  LIMIT match_count;
$function$;

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$;
CREATE TRIGGER update_ornaments_updated_at BEFORE UPDATE ON public.ornaments FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
CREATE TRIGGER update_music_updated_at BEFORE UPDATE ON public.music FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
CREATE TRIGGER trg_user_proficiency_updated_at BEFORE UPDATE ON public.user_proficiency_state FOR EACH ROW EXECUTE FUNCTION update_user_proficiency_updated_at();
