CREATE POLICY "Allow public read access to events" ON public."events" AS PERMISSIVE FOR SELECT TO "public" USING (true);
CREATE POLICY "Users can insert their own quizzes" ON public."quiz_session" AS PERMISSIVE FOR INSERT TO "public" WITH CHECK (((auth.uid())::text = (user_id)::text));
CREATE POLICY "Users can update their own quizzes" ON public."quiz_session" AS PERMISSIVE FOR UPDATE TO "public" USING (((auth.uid())::text = (user_id)::text));
CREATE POLICY "Users can view their own quizzes" ON public."quiz_session" AS PERMISSIVE FOR SELECT TO "public" USING (((auth.uid())::text = (user_id)::text));
CREATE POLICY "Users can insert questions for their quizzes" ON public."quiz_question" AS PERMISSIVE FOR INSERT TO "public" WITH CHECK ((EXISTS ( SELECT 1
   FROM quiz_session s
  WHERE ((s.id = quiz_question.quiz_id) AND ((s.user_id)::text = (auth.uid())::text)))));
CREATE POLICY "Users can update questions for their quizzes" ON public."quiz_question" AS PERMISSIVE FOR UPDATE TO "public" USING ((EXISTS ( SELECT 1
   FROM quiz_session s
  WHERE ((s.id = quiz_question.quiz_id) AND ((s.user_id)::text = (auth.uid())::text)))));
CREATE POLICY "Users can view their own quiz questions" ON public."quiz_question" AS PERMISSIVE FOR SELECT TO "public" USING ((EXISTS ( SELECT 1
   FROM quiz_session s
  WHERE ((s.id = quiz_question.quiz_id) AND ((s.user_id)::text = (auth.uid())::text)))));
CREATE POLICY "Users can insert their own proficiency" ON public."user_proficiency_state" AS PERMISSIVE FOR INSERT TO "public" WITH CHECK (((auth.uid())::text = (user_id)::text));
CREATE POLICY "Users can update their own proficiency" ON public."user_proficiency_state" AS PERMISSIVE FOR UPDATE TO "public" USING (((auth.uid())::text = (user_id)::text));
CREATE POLICY "Users can view their own proficiency" ON public."user_proficiency_state" AS PERMISSIVE FOR SELECT TO "public" USING (((auth.uid())::text = (user_id)::text));
CREATE POLICY "Users can manage their own sessions" ON public."sessions" AS PERMISSIVE FOR ALL TO "public" USING ((((auth.uid() IS NOT NULL) AND (auth.uid() = user_id)) OR ((auth.uid() IS NULL) AND (user_id IS NULL))));
CREATE POLICY "Users can manage their own messages" ON public."messages" AS PERMISSIVE FOR ALL TO "public" USING ((EXISTS ( SELECT 1
   FROM sessions
  WHERE ((sessions.id = messages.session_id) AND (((auth.uid() IS NOT NULL) AND (sessions.user_id = auth.uid())) OR ((auth.uid() IS NULL) AND (sessions.user_id IS NULL)))))));

-- Development baseline deliberately limits content writes to the backend service role.
CREATE POLICY "Public read music" ON public.music FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Public read ornaments" ON public.ornaments FOR SELECT TO anon, authenticated USING (true);
